using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using UnityEditor;
[InitializeOnLoad]public static class CityFlareCheck{
static CityFlareCheck(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityFlareCheck.request"))return;File.Delete("CityFlareCheck.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/NaturalDayNight/FlareCheck.txt",e.ToString());}}
static void Run(){var s=SceneManager.GetActiveScene();var roots=s.GetRootGameObjects();var b=new StringBuilder();b.AppendLine("Scene="+s.path+" quality="+QualitySettings.names[QualitySettings.GetQualityLevel()]+" pipeline="+AssetDatabase.GetAssetPath(GraphicsSettings.currentRenderPipeline));b.AppendLine("Sky="+AssetDatabase.GetAssetPath(RenderSettings.skybox)+" fog="+RenderSettings.fog+" ambient="+RenderSettings.ambientSkyColor+" reflection="+RenderSettings.reflectionIntensity);
foreach(var c in roots.SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true))){b.AppendLine("Controller enabled="+c.enabled+" active="+c.gameObject.activeInHierarchy+" night="+c.IsNight+" sun="+c.sun.transform.eulerAngles+" intensity="+c.sun.intensity+" color="+c.sun.color);foreach(var f in c.sunFlares)if(f)b.AppendLine("Flare="+f.GetType()+" enabled="+f.enabled+" active="+f.gameObject.activeInHierarchy+" json="+EditorJsonUtility.ToJson(f));}
foreach(var c in roots.SelectMany(x=>x.GetComponentsInChildren<Camera>(true)))b.AppendLine("Camera="+c.name+" enabled="+c.enabled+" active="+c.gameObject.activeInHierarchy+" position="+c.transform.position+" rotation="+c.transform.eulerAngles);
if(SceneView.lastActiveSceneView){var v=SceneView.lastActiveSceneView;b.AppendLine("SceneView effects="+EditorJsonUtility.ToJson(v.sceneViewState)+" lighting="+v.sceneLighting+" position="+v.camera.transform.position+" rotation="+v.camera.transform.eulerAngles);}
var ctrl=roots.SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true)).Single(); ctrl.Apply(false); foreach(var cam in roots.SelectMany(x=>x.GetComponentsInChildren<Camera>(true)).Where(x=>x.gameObject.activeInHierarchy)){var data=UnityEngine.Rendering.Universal.CameraExtensions.GetUniversalAdditionalCameraData(cam); data.renderPostProcessing=true; EditorUtility.SetDirty(data);} UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(s); UnityEditor.SceneManagement.EditorSceneManager.SaveScene(s); foreach(var f in ctrl.sunFlares)if(f){f.enabled=false;f.enabled=true;} Action<Scene,Vector3,Vector3,string> cap=Capture; var pos=new Vector3(-62,70,230); cap(s,pos,pos-ctrl.sun.transform.forward*500,"NaturalDayNight/Restored-Sun-Flare"); foreach(var f in ctrl.sunFlares)if(f)f.enabled=false; cap(s,pos,pos-ctrl.sun.transform.forward*500,"NaturalDayNight/Flare-Diagnostic-Off"); foreach(var f in ctrl.sunFlares)if(f)f.enabled=true; cap(s,new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f),"NaturalDayNight/Restored-Hospital"); b.AppendLine("Original flare re-registered; captured original day lighting facing sun and hospital."); File.WriteAllText("FinalEnvironmentRoadReview/NaturalDayNight/FlareCheck.txt",b.ToString());}static void Capture(Scene scene,Vector3 p,Vector3 target,string name){var go=new GameObject("Flare verification"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();cam.enabled=false;cam.farClipPlane=5000;cam.fieldOfView=62;cam.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p));UnityEngine.Rendering.Universal.CameraExtensions.GetUniversalAdditionalCameraData(cam).renderPostProcessing=true;var rt=RenderTexture.GetTemporary(1400,1000,24);var old=RenderTexture.active;try{cam.targetTexture=rt;for(int i=0;i<4;i++)cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1400,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1400,1000),0,0);tex.Apply();File.WriteAllBytes("FinalEnvironmentRoadReview/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=old;cam.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
